package resolver

import (
	"context"
	"crypto/tls"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

const (
	maxRetries     = 3
	retryBackoff   = 100 * time.Millisecond
	rateLimit      = 50
	ratePeriod     = time.Second
	dnsTimeout     = 5 * time.Second
	maxRedirects   = 10
)

type RateLimiter struct {
	mu       sync.Mutex
	tokens   int
	lastFill time.Time
}

func NewRateLimiter() *RateLimiter {
	return &RateLimiter{tokens: rateLimit, lastFill: time.Now()}
}

func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	elapsed := now.Sub(rl.lastFill)
	if elapsed >= ratePeriod {
		rl.tokens = rateLimit
		rl.lastFill = now
	}
	if rl.tokens > 0 {
		rl.tokens--
		return true
	}
	return false
}

type AuthTransport struct {
	Base         http.RoundTripper
	NTLMDomain   string
	NTLMUser     string
	NTLMPassword string
	allowedHost  string
}

func (t *AuthTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	if req.URL.Host != t.allowedHost {
		return nil, fmt.Errorf("request to unauthorized host: %s", req.URL.Host)
	}
	resp, err := t.Base.RoundTrip(req)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode == http.StatusUnauthorized {
		authHeader := resp.Header.Get("WWW-Authenticate")
		if strings.HasPrefix(authHeader, "NTLM") || strings.HasPrefix(authHeader, "Negotiate") {
			resp.Body.Close()
			return t.performNTLMAuth(req, authHeader)
		}
	}
	return resp, nil
}

func (t *AuthTransport) performNTLMAuth(req *http.Request, challenge string) (*http.Response, error) {
	if req.URL.Host != t.allowedHost {
		return nil, fmt.Errorf("NTLM auth to unauthorized host: %s", req.URL.Host)
	}
	negotiateMsg := generateNTLMNegotiate(t.NTLMDomain)
	req.Header.Set("Authorization", "NTLM "+negotiateMsg)
	return t.Base.RoundTrip(req)
}

func generateNTLMNegotiate(domain string) string {
	return fmt.Sprintf("TlRMTVNTUAABAAAAB4IIogAAAAAAAAAAAAAAAAAAAAAGAbEdAAAADw==%s", domain)
}

type DNSResolver struct {
	upstreamURL  string
	upstreamHost string
	client      *http.Client
	rateLimiter *RateLimiter
}

func NewDNSResolver(upstreamURL string, ntlmDomain, ntlmUser, ntlmPass string) *DNSResolver {
	parsed, err := url.Parse(upstreamURL)
	if err != nil {
		panic(fmt.Sprintf("invalid upstream URL: %v", err))
	}
	allowedHost := parsed.Host

	transport := &AuthTransport{
		Base: &http.Transport{
			TLSClientConfig: &tls.Config{
				MinVersion: tls.VersionTLS12,
			},
			DialContext: (&net.Dialer{
				Timeout: dnsTimeout,
			}).DialContext,
		},
		NTLMDomain:   ntlmDomain,
		NTLMUser:     ntlmUser,
		NTLMPassword: ntlmPass,
		allowedHost:  allowedHost,
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   dnsTimeout * 2,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= maxRedirects {
				return fmt.Errorf("too many redirects")
			}
			if req.URL.Host != allowedHost {
				return fmt.Errorf("redirect to unauthorized host: %s", req.URL.Host)
			}
			return nil
		},
	}

	return &DNSResolver{
		upstreamURL:  upstreamURL,
		upstreamHost: allowedHost,
		client:      client,
		rateLimiter: NewRateLimiter(),
	}
}

func (r *DNSResolver) Resolve(ctx context.Context, query string, qtype string) (string, error) {
	if !r.rateLimiter.Allow() {
		return "", fmt.Errorf("rate limit exceeded")
	}

	var lastErr error
	for attempt := 0; attempt <= maxRetries; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return "", ctx.Err()
			case <-time.After(retryBackoff * time.Duration(attempt)):
			}
		}

		result, err := r.doResolve(ctx, query, qtype)
		if err == nil {
			return result, nil
		}
		lastErr = err
	}
	return "", fmt.Errorf("resolution failed after %d retries: %w", maxRetries, lastErr)
}

func (r *DNSResolver) doResolve(ctx context.Context, query string, qtype string) (string, error) {
	safeQuery := url.QueryEscape(query)
	safeType := url.QueryEscape(qtype)
	reqURL := fmt.Sprintf("%s/dns-query?name=%s&type=%s", r.upstreamURL, safeQuery, safeType)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, reqURL, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Accept", "application/dns-json")

	resp, err := r.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("upstream returned status %d", resp.StatusCode)
	}

	buf := make([]byte, 4096)
	n, _ := resp.Body.Read(buf)
	return string(buf[:n]), nil
}
